{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Elbasvir, the closest structural analogue sharing the same carbamate-proline-imidazole NS5A inhibitor scaffold, has an absolute oral bioavailability of approximately 32% in HCV-infected subjects, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Ledipasvir, another HCV NS5A inhibitor with the same terminal carbamate-proline-imidazole motif, has an estimated oral bioavailability of 53%, further demonstrating that this large lipophilic scaffold can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest experimental analogues, elbasvir and ledipasvir, are HCV NS5A inhibitors with the same carbamate-proline-imidazole arms and oral bioavailability values of 32% and 53%, respectively, both above the 20% threshold. Although the physicochemical prior is unfavorable, direct experimental evidence from structurally related compounds overrides it; the query is predicted to have high oral bioavailability (F ≥ 20%).",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself; closest analogues have moderate Morgan similarity (0.61 and 0.44).",
    "No query-specific human PK data under fasted conditions; extrapolation relies on structural analogy to elbasvir and ledipasvir."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

